// Package sqlite implements filament.DataStore, filament.ScheduleStore, and
// the pipeline store on SQLite via the CGO-free modernc driver, with queries
// generated by sqlc from datastore/sqlite/queries/*.sql.
//
// The dialect differs from datastore/postgres deliberately: times are unix
// milliseconds, JSON columns are TEXT, ids are TEXT UUIDs minted in Go, and
// the single-writer connection provides the serialization Postgres expresses
// with FOR UPDATE.
package sqlite

import (
	"context"
	"database/sql"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"time"

	_ "modernc.org/sqlite" // registers the "sqlite" database/sql driver

	"github.com/galaxy-io/filament"
	"github.com/galaxy-io/filament/datastore/sqlite/sqlcgen"
)

// Store is a SQLite-backed filament.DataStore and filament.ScheduleStore.
type Store struct {
	db *sql.DB
	q  *sqlcgen.Queries
}

var (
	_ filament.DataStore             = (*Store)(nil)
	_ filament.RunTransitionStore    = (*Store)(nil)
	_ filament.ScheduleStore         = (*Store)(nil)
	_ filament.PipelineScheduleStore = (*Store)(nil)
)

// Open opens (creating if needed) the database at path, applies pragmas and
// migrations, and returns the store. ":memory:" opens a private in-memory
// database with the same enforcement as a file.
func Open(path string) (*Store, error) {
	if path != ":memory:" {
		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
			return nil, fmt.Errorf("datastore/sqlite: create directory: %w", err)
		}
	}
	pragmas := url.Values{"_pragma": []string{"busy_timeout(5000)", "journal_mode(WAL)", "foreign_keys(1)", "synchronous(NORMAL)"}}
	dsn := (&url.URL{Scheme: "file", OmitHost: true, Path: path, RawQuery: pragmas.Encode()}).String()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("datastore/sqlite: open: %w", err)
	}
	// One connection serializes every transaction and keeps an in-memory
	// database from splitting across pool connections.
	db.SetMaxOpenConns(1)
	if err := Migrate(db); err != nil {
		_ = db.Close()
		return nil, err
	}
	return New(db), nil
}

// New wraps an already-open handle. Run Migrate before first use.
func New(db *sql.DB) *Store { return &Store{db: db, q: sqlcgen.New(db)} }

// NewMemory opens a private in-memory store. Opening one cannot realistically
// fail, so failure panics rather than making every throwaway store two-valued.
func NewMemory() *Store {
	store, err := Open(":memory:")
	if err != nil {
		panic(fmt.Sprintf("datastore/sqlite: open in-memory store: %v", err))
	}
	return store
}

// DB exposes the underlying handle for components backed by the same database.
func (s *Store) DB() *sql.DB { return s.db }

// Ping verifies database reachability.
func (s *Store) Ping(ctx context.Context) error { return s.db.PingContext(ctx) }

// Close releases the underlying handle.
func (s *Store) Close() error { return s.db.Close() }

// Name identifies this store implementation.
func (s *Store) Name() string { return "sqlite" }

func nowMillis() int64 { return time.Now().UnixMilli() }

// nullMillis renders a lifecycle stamp for a nullable column; zero means unset.
func nullMillis(t time.Time) sql.NullInt64 {
	if t.IsZero() {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: t.UnixMilli(), Valid: true}
}

func nullMillisPtr(t *time.Time) sql.NullInt64 {
	if t == nil {
		return sql.NullInt64{}
	}
	return nullMillis(*t)
}

func millisTime(v int64) time.Time {
	if v == 0 {
		return time.Time{}
	}
	return time.UnixMilli(v)
}

func timeFrom(v sql.NullInt64) *time.Time {
	if !v.Valid {
		return nil
	}
	t := time.UnixMilli(v.Int64)
	return &t
}

func derefTime(t *time.Time) time.Time {
	if t == nil {
		return time.Time{}
	}
	return *t
}

// deleteStamp renders the suffix soft deletes append to free the name for
// reuse, mirroring the postgres store's to_char formatting. It takes the
// delete's own millis so the stamp and deleted_at agree exactly.
func deleteStamp(nowMs int64) string {
	return "__deleted__" + time.UnixMilli(nowMs).UTC().Format("2006-01-02T15:04:05.000Z")
}
